D[60378]={"^Increases the duration of Psychic Scream by 2 sec%.%s*$","Aumenta a duração do Grito Psíquico em 2 s."}
D[60379]={"^Permanently adds 20 Fire resistance to a leg or head slot item%.%s*$","Permanente. Adiciona 20 resistência ao Fogo a um item dá espaço de perna ou cabeça."}
D[60380]={"^Permanently adds 8 Strength to a leg or head slot item%.%s*$","Permanente. Adiciona 8 força a um item dá espaço de perna ou cabeça."}
D[60381]={"^Permanently adds 8 Stamina to a leg or head slot item%.%s*$","Permanente: agrega 8 vigor a um item dá espaço de perna ou cabeça."}
D[60382]={"^Permanently adds 8 Agility to a leg or head slot item%.%s*$","Permanente: agrega 8 agilidada um item dá espaço de perna ou cabeça."}
D[60383]={"^Permanently adds 8 Intellect to a leg or head slot item%.%s*$","Permanente: agrega 8 intelecto a um item dá espaço de perna ou cabeça."}
