D[63927]={"^Critical strike chance increased by (.-)%%, stacking (.-) times%.%s*$","Aumenta a chance de acerto crítico em {{1}}%, acumulando-se até {{2}} vezes."}
D[63928]={"^Increases your healing done to allies below 35%% health by (.-)%%%.%s*$","Aumenta sua cura realizada a aliados abaixo de 35% de vida em {{1}}%."}
